package kz.zeroops.agent;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="agent.execution-mode",havingValue="dry-run",matchIfMissing=true) class DryRunDeploymentExecutor implements DeploymentExecutor { public ExecutionResult execute(AgentBoundary.Manifest m,java.util.function.Consumer<String> log){log.accept("Dry-run: signed manifest accepted; Docker access is disabled.");return new ExecutionResult(true,"Manifest verified; dry-run executor completed without Docker access.",null,m.applicationPort(),m.publicPort()==0?null:m.publicPort(),m.runtime(),m.healthPath(),java.util.List.of());} }
